def _get_location(request, location, default):
    """Read a single location (``json``, ``args``, ``headers``, ...) off of a
    request, reporting an unusable JSON body as simply absent.

    Werkzeug >= 2.1 raises a :class:`~werkzeug.exceptions.BadRequest` from
    ``request.json`` when the request carries no JSON body at all, where it
    used to return ``None``.  An argument that merely looks in the JSON body
    -- which the default location does -- must not turn a plain query string
    request into a client error, so that case is reported as missing.  A body
    that announces itself as JSON but fails to parse is still a real
    ``BadRequest`` and is left to propagate.
    """
    try:
        return getattr(request, location, default)
    except exceptions.BadRequest:
        if getattr(request, 'is_json', False):
            raise
        return default


